import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

public class StdKeyDeserializer_deserializeKey_TriageGen1Test {

    private DeserializationContext mockCtxt;
    private DeserializationConfig mockConfig;

    @Before
    public void setUp() {
        mockCtxt = mock(DeserializationContext.class);
        mockConfig = mock(DeserializationConfig.class);
        when(mockCtxt.getConfig()).thenReturn(mockConfig);
    }

    /**
     * Concrete implementation to test the protected _parse method and access constructor.
     */
    private static class TestKeyDeserializer extends StdKeyDeserializer {
        private final boolean throwException;
        private final Object parseResult;

        public TestKeyDeserializer(Class<?> cls, boolean throwException, Object parseResult) {
            super(0, cls);
            this.throwException = throwException;
            this.parseResult = parseResult;
        }

        @Override
        protected Object _parse(String key, DeserializationContext ctxt) throws Exception {
            if (throwException) {
                throw new RuntimeException("Parse error");
            }
            return parseResult;
        }
    }

    @Test
    public void testDeserializeKey_NullKey() throws IOException {
        StdKeyDeserializer deserializer = new TestKeyDeserializer(String.class, false, "val");
        Object result = deserializer.deserializeKey(null, mockCtxt);
        assertNull(result);
        verifyNoInteractions(mockCtxt);
    }

    @Test
    public void testDeserializeKey_Success() throws IOException {
        StdKeyDeserializer deserializer = new TestKeyDeserializer(String.class, false, "success");
        Object result = deserializer.deserializeKey("valid", mockCtxt);
        assertEquals("success", result);
    }

    @Test
    public void testDeserializeKey_ParseException() throws IOException {
        String key = "bad_key";
        StdKeyDeserializer deserializer = new TestKeyDeserializer(String.class, true, null);

        Object expectedError = "error_handle";
        when(mockCtxt.handleWeirdKey(eq(String.class), eq(key), anyString())).thenReturn(expectedError);

        Object result = deserializer.deserializeKey(key, mockCtxt);

        assertEquals(expectedError, result);
        verify(mockCtxt).handleWeirdKey(eq(String.class), eq(key), contains("RuntimeException"));
    }

    @Test
    public void testDeserializeKey_ParseReturnsNull_NotEnum() throws IOException {
        String key = "null_result_key";
        StdKeyDeserializer deserializer = new TestKeyDeserializer(Integer.class, false, null);

        Object expectedError = "weird_key_error";
        when(mockCtxt.handleWeirdKey(eq(Integer.class), eq(key), eq("not a valid representation"))).thenReturn(expectedError);

        Object result = deserializer.deserializeKey(key, mockCtxt);

        assertEquals(expectedError, result);
    }

    @Test
    public void testDeserializeKey_ParseReturnsNull_IsEnum_WithFeatureEnabled() throws IOException {
        String key = "unknown_enum";
        StdKeyDeserializer deserializer = new TestKeyDeserializer(TestEnum.class, false, null);

        when(mockConfig.isEnabled(DeserializationFeature.READ_UNKNOWN_ENUM_VALUES_AS_NULL)).thenReturn(true);

        Object result = deserializer.deserializeKey(key, mockCtxt);

        assertNull(result);
    }

    @Test
    public void testDeserializeKey_ParseReturnsNull_IsEnum_WithFeatureDisabled() throws IOException {
        String key = "unknown_enum";
        StdKeyDeserializer deserializer = new TestKeyDeserializer(TestEnum.class, false, null);

        when(mockConfig.isEnabled(DeserializationFeature.READ_UNKNOWN_ENUM_VALUES_AS_NULL)).thenReturn(false);
        Object expectedError = "weird_enum_error";
        when(mockCtxt.handleWeirdKey(eq(TestEnum.class), eq(key), eq("not a valid representation"))).thenReturn(expectedError);

        Object result = deserializer.deserializeKey(key, mockCtxt);

        assertEquals(expectedError, result);
    }

    private enum TestEnum {
        VAL1, VAL2
    }
}
